00072 inline static uint32_t getRasterIdx(const Position& pos, const PreCalcValues& pcv)
00073 {
00074   return ( ( pos.x & pcv.maxCUWidthMask ) >> pcv.minCUWidthLog2 ) + ( ( pos.y & pcv.maxCUHeightMask ) >> pcv.minCUHeightLog2 ) * pcv.partsInCtuWidth;
00075 }
