00106 void LoopFilter::create( const unsigned uiMaxCUDepth )
00107 {
00108   destroy();
00109   const unsigned numPartitions = 1 << ( uiMaxCUDepth << 1 );
00110   for( int edgeDir = 0; edgeDir < NUM_EDGE_DIR; edgeDir++ )
00111   {
00112     m_aapucBS       [edgeDir].resize( numPartitions );
00113     m_aapbEdgeFilter[edgeDir].resize( numPartitions );
00114   }
00115   m_enc = false;
00116 }
00117 
00118 void LoopFilter::initEncPicYuvBuffer(ChromaFormat chromaFormat, const Size &size, const unsigned maxCUSize)
00119 {
00120   const Area a = Area(Position(), size);
00121   m_encPicYuvBuffer.destroy();
00122   m_encPicYuvBuffer.create(chromaFormat, a, maxCUSize, 7);
00123 }
