00125 void LoopFilter::destroy()
00126 {
00127   for( int edgeDir = 0; edgeDir < NUM_EDGE_DIR; edgeDir++ )
00128   {
00129     m_aapucBS       [edgeDir].clear();
00130     m_aapbEdgeFilter[edgeDir].clear();
00131   }
00132   m_encPicYuvBuffer.destroy();
00133 }
