00140 void LoopFilter::loopFilterPic( CodingStructure& cs
00141                                 )
00142 {
00143   const PreCalcValues& pcv = *cs.pcv;
00144   m_shiftHor = ::getComponentScaleX( COMPONENT_Cb, cs.pcv->chrFormat );
00145   m_shiftVer = ::getComponentScaleY( COMPONENT_Cb, cs.pcv->chrFormat );
00146 
00147   DTRACE_UPDATE( g_trace_ctx, ( std::make_pair( "poc", cs.slice->getPOC() ) ) );
00148 #if ENABLE_TRACING
00149   for( int y = 0; y < pcv.heightInCtus; y++ )
00150   {
00151     for( int x = 0; x < pcv.widthInCtus; x++ )
00152     {
00153       const UnitArea ctuArea( pcv.chrFormat, Area( x << pcv.maxCUWidthLog2, y << pcv.maxCUHeightLog2, pcv.maxCUWidth, pcv.maxCUWidth ) );
00154       DTRACE    ( g_trace_ctx, D_CRC, "CTU %d %d", ctuArea.Y().x, ctuArea.Y().y );
00155       DTRACE_CRC( g_trace_ctx, D_CRC, cs, cs.picture->getRecoBuf( clipArea( ctuArea, *cs.picture ) ), &ctuArea.Y() );
00156     }
00157   }
00158 #endif
00159 
00160   for( int y = 0; y < pcv.heightInCtus; y++ )
00161   {
00162     for( int x = 0; x < pcv.widthInCtus; x++ )
00163     {
00164       memset( m_aapucBS       [EDGE_VER].data(), 0,     m_aapucBS       [EDGE_VER].byte_size() );
00165       memset( m_aapbEdgeFilter[EDGE_VER].data(), false, m_aapbEdgeFilter[EDGE_VER].byte_size() );
00166       memset( m_maxFilterLengthP, 0, sizeof(m_maxFilterLengthP) );
00167       memset( m_maxFilterLengthQ, 0, sizeof(m_maxFilterLengthQ) );
00168       memset( m_transformEdge, false, sizeof(m_transformEdge) );
00169       m_ctuXLumaSamples = x << pcv.maxCUWidthLog2;
00170       m_ctuYLumaSamples = y << pcv.maxCUHeightLog2;
00171 
00172       const UnitArea ctuArea( pcv.chrFormat, Area( x << pcv.maxCUWidthLog2, y << pcv.maxCUHeightLog2, pcv.maxCUWidth, pcv.maxCUWidth ) );
00173       CodingUnit* firstCU = cs.getCU( ctuArea.lumaPos(), CH_L);
00174       cs.slice = firstCU->slice;
00175 
00176       // CU-based deblocking
00177       for( auto &currCU : cs.traverseCUs( CS::getArea( cs, ctuArea, CH_L ), CH_L ) )
00178       {
00179         xDeblockCU( currCU, EDGE_VER );
00180       }
00181 
00182       if( CS::isDualITree( cs ) )
00183       {
00184         memset( m_aapucBS       [EDGE_VER].data(), 0,     m_aapucBS       [EDGE_VER].byte_size() );
00185         memset( m_aapbEdgeFilter[EDGE_VER].data(), false, m_aapbEdgeFilter[EDGE_VER].byte_size() );
00186         memset( m_maxFilterLengthP, 0, sizeof(m_maxFilterLengthP) );
00187         memset( m_maxFilterLengthQ, 0, sizeof(m_maxFilterLengthQ) );
00188         memset( m_transformEdge, false, sizeof(m_transformEdge) );
00189 
00190         for( auto &currCU : cs.traverseCUs( CS::getArea( cs, ctuArea, CH_C ), CH_C ) )
00191         {
00192           xDeblockCU( currCU, EDGE_VER );
00193         }
00194       }
00195     }
00196   }
00197 
00198   // Vertical filtering
00199   for( int y = 0; y < pcv.heightInCtus; y++ )
00200   {
00201     for( int x = 0; x < pcv.widthInCtus; x++ )
00202     {
00203       memset( m_aapucBS       [EDGE_HOR].data(), 0,     m_aapucBS       [EDGE_HOR].byte_size() );
00204       memset( m_aapbEdgeFilter[EDGE_HOR].data(), false, m_aapbEdgeFilter[EDGE_HOR].byte_size() );
00205       memset( m_maxFilterLengthP, 0, sizeof(m_maxFilterLengthP) );
00206       memset( m_maxFilterLengthQ, 0, sizeof(m_maxFilterLengthQ) );
00207       memset( m_transformEdge, false, sizeof(m_transformEdge) );
00208       m_ctuXLumaSamples = x << pcv.maxCUWidthLog2;
00209       m_ctuYLumaSamples = y << pcv.maxCUHeightLog2;
00210 
00211       const UnitArea ctuArea( pcv.chrFormat, Area( x << pcv.maxCUWidthLog2, y << pcv.maxCUHeightLog2, pcv.maxCUWidth, pcv.maxCUWidth ) );
00212       CodingUnit* firstCU = cs.getCU( ctuArea.lumaPos(), CH_L);
00213       cs.slice = firstCU->slice;
00214 
00215       // CU-based deblocking
00216       for( auto &currCU : cs.traverseCUs( CS::getArea( cs, ctuArea, CH_L ), CH_L ) )
00217       {
00218         xDeblockCU( currCU, EDGE_HOR );
00219       }
00220 
00221       if( CS::isDualITree( cs ) )
00222       {
00223         memset( m_aapucBS       [EDGE_HOR].data(), 0,     m_aapucBS       [EDGE_HOR].byte_size() );
00224         memset( m_aapbEdgeFilter[EDGE_HOR].data(), false, m_aapbEdgeFilter[EDGE_HOR].byte_size() );
00225         memset( m_maxFilterLengthP, 0, sizeof(m_maxFilterLengthP) );
00226         memset( m_maxFilterLengthQ, 0, sizeof(m_maxFilterLengthQ) );
00227         memset( m_transformEdge, false, sizeof(m_transformEdge) );
00228 
00229         for( auto &currCU : cs.traverseCUs( CS::getArea( cs, ctuArea, CH_C ), CH_C ) )
00230         {
00231           xDeblockCU( currCU, EDGE_HOR );
00232         }
00233       }
00234     }
00235   }
00236 
00237   DTRACE_PIC_COMP(D_REC_CB_LUMA_LF,   cs, cs.getRecoBuf(), COMPONENT_Y);
00238   DTRACE_PIC_COMP(D_REC_CB_CHROMA_LF, cs, cs.getRecoBuf(), COMPONENT_Cb);
00239   DTRACE_PIC_COMP(D_REC_CB_CHROMA_LF, cs, cs.getRecoBuf(), COMPONENT_Cr);
00240 
00241   DTRACE    ( g_trace_ctx, D_CRC, "LoopFilter" );
00242   DTRACE_CRC( g_trace_ctx, D_CRC, cs, cs.getRecoBuf() );
00243 }
00244 
00245 void LoopFilter::resetFilterLengths()
00246 {
00247   memset(m_aapucBS[EDGE_VER].data(), 0, m_aapucBS[EDGE_VER].byte_size());
00248   memset(m_aapbEdgeFilter[EDGE_VER].data(), false, m_aapbEdgeFilter[EDGE_VER].byte_size());
00249   memset(m_aapucBS[EDGE_HOR].data(), 0, m_aapucBS[EDGE_HOR].byte_size());
00250   memset(m_aapbEdgeFilter[EDGE_HOR].data(), false, m_aapbEdgeFilter[EDGE_HOR].byte_size());
00251   memset(m_maxFilterLengthP, 0, sizeof(m_maxFilterLengthP));
00252   memset(m_maxFilterLengthQ, 0, sizeof(m_maxFilterLengthQ));
00253   memset(m_transformEdge, false, sizeof(m_transformEdge));
00254 }
