00256 // ====================================================================================================================
00257 // Protected member functions
00258 // ====================================================================================================================
00259 
00266 void LoopFilter::xDeblockCU( CodingUnit& cu, const DeblockEdgeDir edgeDir )
00267 {
00268   const PreCalcValues& pcv = *cu.cs->pcv;
00269   const Area area          = cu.Y().valid() ? cu.Y() : Area( recalcPosition( cu.chromaFormat, cu.chType, CHANNEL_TYPE_LUMA, cu.blocks[cu.chType].pos() ), recalcSize( cu.chromaFormat, cu.chType, CHANNEL_TYPE_LUMA, cu.blocks[cu.chType].size() ) );
00270 
00271   bool horEdgeFilter = false, verEdgeFilter = false;
00272   int  numHorVirBndry = 0, numVerVirBndry = 0;
00273   int  horVirBndryPos[] = { 0, 0, 0 };
00274   int  verVirBndryPos[] = { 0, 0, 0 };
00275 
00276   bool isCuCrossedByVirtualBoundaries = isCrossedByVirtualBoundaries( area.x, area.y, area.width, area.height, numHorVirBndry, numVerVirBndry, horVirBndryPos, verVirBndryPos, cu.cs->picHeader );
00277 
00278   xSetLoopfilterParam( cu );
00279   static_vector<int, 2*MAX_CU_SIZE> edgeIdx;
00280   edgeIdx.clear();
00281 
00282   if (m_enc)
00283   {
00284     m_shiftHor = ::getComponentScaleX(COMPONENT_Cb, cu.chromaFormat);
00285     m_shiftVer = ::getComponentScaleY(COMPONENT_Cb, cu.chromaFormat);
00286     int x, y;
00287     if (cu.Y().valid())
00288     {
00289       x = cu.block(COMPONENT_Y).x;
00290       y = cu.block(COMPONENT_Y).y;
00291     }
00292     else
00293     {
00294       x = cu.block(COMPONENT_Cb).x << m_shiftHor;
00295       y = cu.block(COMPONENT_Cb).y << m_shiftVer;
00296     }
00297     m_ctuXLumaSamples = x & ~(cu.slice->getSPS()->getMaxCUWidth()  - 1);
00298     m_ctuYLumaSamples = y & ~(cu.slice->getSPS()->getMaxCUHeight() - 1);
00299   }
00300 
00301   for( auto &currTU : CU::traverseTUs( cu ) )
00302   {
00303     const Area& areaTu = cu.Y().valid() ? currTU.block( COMPONENT_Y ) : Area( recalcPosition( cu.chromaFormat, cu.chType, CHANNEL_TYPE_LUMA, currTU.blocks[cu.chType].pos() ), recalcSize( cu.chromaFormat, cu.chType, CHANNEL_TYPE_LUMA, currTU.blocks[cu.chType].size() ) );
00304 
00305     verEdgeFilter = m_stLFCUParam.internalEdge;
00306     horEdgeFilter = m_stLFCUParam.internalEdge;
00307 
00308     if ((edgeDir == EDGE_HOR && areaTu.y % 4 != 0) || (edgeDir == EDGE_VER && areaTu.x % 4 != 0))
00309     {
00310       if (cu.chromaFormat != CHROMA_400 && currTU.block(COMPONENT_Cb).valid())
00311       {
00312         if ((edgeDir == EDGE_HOR && currTU.block(COMPONENT_Cb).y % 4 == 0)
00313             || (edgeDir == EDGE_VER && currTU.block(COMPONENT_Cb).x % 4 == 0))
00314         {
00315           // Set max filter length for chroma in narrow/short CUs that use ISP mode
00316           xSetMaxFilterLengthPQFromTransformSizes(edgeDir, cu, currTU, COMPONENT_Cb);
00317         }
00318       }
00319       continue;
00320     }
00321 
00322     if( isCuCrossedByVirtualBoundaries )
00323     {
00324       xDeriveEdgefilterParam( areaTu.x, areaTu.y, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos, verEdgeFilter, horEdgeFilter );
00325     }
00326     xSetEdgefilterMultiple( cu, EDGE_VER, areaTu, verEdgeFilter );
00327     xSetEdgefilterMultiple( cu, EDGE_HOR, areaTu, horEdgeFilter );
00328     xSetMaxFilterLengthPQFromTransformSizes(edgeDir, cu, currTU, COMPONENT_Y);
00329     if( cu.Y().valid() )
00330     {
00331       edgeIdx.push_back( ( edgeDir == EDGE_HOR ) ? ( currTU.blocks[cu.chType].y - cu.blocks[cu.chType].y ) / 4 : ( currTU.blocks[cu.chType].x - cu.blocks[cu.chType].x ) / 4 );
00332     }
00333     else
00334     {
00335       edgeIdx.push_back( ( edgeDir == EDGE_HOR ) ? (( currTU.blocks[cu.chType].y - cu.blocks[cu.chType].y ) << ::getComponentScaleY(COMPONENT_Cb, cu.chromaFormat))  / 4 : (( currTU.blocks[cu.chType].x - cu.blocks[cu.chType].x ) << ::getComponentScaleX(COMPONENT_Cb, cu.chromaFormat)) / 4 );
00336     }
00337   }
00338 
00339   bool mvSubBlocks = false;
00340   int subBlockSize = 8;
00341   for( auto &currPU : CU::traversePUs( cu ) )
00342   {
00343     const Area& areaPu = cu.Y().valid() ? currPU.block( COMPONENT_Y ) : area;
00344     const bool xOff    = currPU.blocks[cu.chType].x != cu.blocks[cu.chType].x;
00345     const bool yOff    = currPU.blocks[cu.chType].y != cu.blocks[cu.chType].y;
00346 
00347     verEdgeFilter = (xOff ? m_stLFCUParam.internalEdge : m_stLFCUParam.leftEdge);
00348     horEdgeFilter = (yOff ? m_stLFCUParam.internalEdge : m_stLFCUParam.topEdge);
00349     if( isCuCrossedByVirtualBoundaries )
00350     {
00351       xDeriveEdgefilterParam( areaPu.x, areaPu.y, numVerVirBndry, numHorVirBndry, verVirBndryPos, horVirBndryPos, verEdgeFilter, horEdgeFilter );
00352     }
00353 
00354     xSetEdgefilterMultiple( cu, EDGE_VER, areaPu, verEdgeFilter, xOff );
00355     xSetEdgefilterMultiple( cu, EDGE_HOR, areaPu, horEdgeFilter, yOff );
00356     edgeIdx.push_back( ( edgeDir == EDGE_HOR ) ? ( currPU.blocks[cu.chType].y - cu.blocks[cu.chType].y ) / 4 : ( currPU.blocks[cu.chType].x - cu.blocks[cu.chType].x ) / 4 );
00357 
00358     if ((currPU.mergeFlag && (currPU.mergeType == MRG_TYPE_SUBPU_ATMVP)) || cu.affine)
00359     {
00360       mvSubBlocks = true;
00361       if (edgeDir == EDGE_HOR)
00362       {
00363         for (uint32_t off = subBlockSize; off < areaPu.height; off += subBlockSize)
00364         {
00365           const Area mvBlockH(cu.Y().x, cu.Y().y + off, cu.Y().width, pcv.minCUHeight);
00366           horEdgeFilter = m_stLFCUParam.internalEdge;
00367           if( isCuCrossedByVirtualBoundaries )
00368           {
00369             xDeriveEdgefilterParam( mvBlockH.x, mvBlockH.y, 0, numHorVirBndry, verVirBndryPos, horVirBndryPos, verEdgeFilter, horEdgeFilter );
00370           }
00371 
00372           xSetEdgefilterMultiple(cu, EDGE_HOR, mvBlockH, horEdgeFilter, 1);
00373           edgeIdx.push_back( ( currPU.blocks[cu.chType].y + off - cu.blocks[cu.chType].y ) / 4 );
00374         }
00375       }
00376       else
00377       {
00378         for (uint32_t off = subBlockSize; off < areaPu.width; off += subBlockSize)
00379         {
00380           const Area mvBlockV(cu.Y().x + off, cu.Y().y, pcv.minCUWidth, cu.Y().height);
00381           verEdgeFilter = m_stLFCUParam.internalEdge;
00382           if( isCuCrossedByVirtualBoundaries )
00383           {
00384             xDeriveEdgefilterParam( mvBlockV.x, mvBlockV.y, numVerVirBndry, 0, verVirBndryPos, horVirBndryPos, verEdgeFilter, horEdgeFilter );
00385           }
00386 
00387           xSetEdgefilterMultiple(cu, EDGE_VER, mvBlockV, verEdgeFilter, 1);
00388           edgeIdx.push_back( ( currPU.blocks[cu.chType].x + off - cu.blocks[cu.chType].x ) / 4 );
00389         }
00390       }
00391     }
00392 
00393     xSetMaxFilterLengthPQForCodingSubBlocks( edgeDir, cu, currPU, mvSubBlocks, subBlockSize, areaPu );
00394   }
00395 
00396   const unsigned uiPelsInPart = pcv.minCUWidth;
00397 
00398   for( int y = 0; y < area.height; y += uiPelsInPart )
00399   {
00400     for( int x = 0; x < area.width; x += uiPelsInPart )
00401     {
00402       unsigned uiBSCheck = 1;
00403       const Position localPos  { area.x + x, area.y + y };
00404       const unsigned rasterIdx = getRasterIdx( localPos, pcv );
00405 
00406       if( m_aapbEdgeFilter[edgeDir][rasterIdx] && uiBSCheck )
00407       {
00408         char bS = 0;
00409         if(cu.treeType != TREE_C)
00410         {
00411           bS |= xGetBoundaryStrengthSingle( cu, edgeDir, localPos, CHANNEL_TYPE_LUMA );
00412         }
00413         if(cu.treeType != TREE_L && cu.chromaFormat != CHROMA_400 && cu.blocks[COMPONENT_Cb].valid())
00414         {
00415           bS |= xGetBoundaryStrengthSingle( cu, edgeDir, localPos, CHANNEL_TYPE_CHROMA );
00416         }
00417         m_aapucBS[edgeDir][rasterIdx] = bS;
00418       }
00419     }
00420   }
00421 
00422 
00423   std::sort( edgeIdx.begin(), edgeIdx.end() );
00424   int prevEdgeIdx = -1;
00425   for ( const int& edge : edgeIdx )
00426   {
00427     if ( edge == prevEdgeIdx ) // skip duplicate edgeIdx marked by both transform and coding subblock processes
00428     {
00429       continue;
00430     }
00431     prevEdgeIdx = edge;
00432 
00433     if ( cu.blocks[COMPONENT_Y].valid() )
00434     {
00435       xEdgeFilterLuma( cu, edgeDir, edge );
00436     }
00437 
00438     if ( pcv.chrFormat != CHROMA_400 && cu.blocks[COMPONENT_Cb].valid() )
00439     {
00440       if ( !cu.ispMode || edge == 0 )
00441       {
00442         xEdgeFilterChroma( cu, edgeDir, edge );
00443       }
00444     }
00445   }
00446 }
00447 
00448 inline bool LoopFilter::isCrossedByVirtualBoundaries(const int xPos, const int yPos, const int width, const int height, int& numHorVirBndry, int& numVerVirBndry, int horVirBndryPos[], int verVirBndryPos[], const PicHeader* picHeader )
00449 {
00450   numHorVirBndry = 0; numVerVirBndry = 0;
00451   if( picHeader->getVirtualBoundariesPresentFlag() )
00452   {
00453     for (int i = 0; i < picHeader->getNumHorVirtualBoundaries(); i++)
00454     {
00455       if (yPos <= picHeader->getVirtualBoundariesPosY(i) && picHeader->getVirtualBoundariesPosY(i) < yPos + height)
00456       {
00457         horVirBndryPos[numHorVirBndry++] = picHeader->getVirtualBoundariesPosY(i);
00458       }
00459     }
00460     for (int i = 0; i < picHeader->getNumVerVirtualBoundaries(); i++)
00461     {
00462       if (xPos <= picHeader->getVirtualBoundariesPosX(i) && picHeader->getVirtualBoundariesPosX(i) < xPos + width)
00463       {
00464         verVirBndryPos[numVerVirBndry++] = picHeader->getVirtualBoundariesPosX(i);
00465       }
00466     }
00467   }
00468   return numHorVirBndry > 0 || numVerVirBndry > 0;
00469 }
00470 
00471 inline void LoopFilter::xDeriveEdgefilterParam( const int xPos, const int yPos, const int numVerVirBndry, const int numHorVirBndry, const int verVirBndryPos[], const int horVirBndryPos[], bool &verEdgeFilter, bool &horEdgeFilter )
00472 {
00473   for (int i = 0; i < numVerVirBndry; i++)
00474   {
00475     if (verVirBndryPos[i] == xPos)
00476     {
00477       verEdgeFilter = false;
00478       break;
00479     }
00480   }
00481 
00482   for (int i = 0; i < numHorVirBndry; i++)
00483   {
00484     if (horVirBndryPos[i] == yPos)
00485     {
00486       horEdgeFilter = false;
00487       break;
00488     }
00489   }
00490 }
00491 
00492 void LoopFilter::xSetMaxFilterLengthPQFromTransformSizes(const DeblockEdgeDir edgeDir, const CodingUnit &cu,
00493                                                          const TransformUnit &currTU, const int firstComponent)
00494 {
00495   const TransformUnit& tuQ = currTU;
00496 
00497   if ( edgeDir == EDGE_HOR )
00498   {
00499     for (int cIdx = firstComponent; cIdx < ::getNumberValidComponents(tuQ.chromaFormat); cIdx++)   // per component
00500     {
00501       const ComponentID comp = ComponentID(cIdx);
00502       const ChannelType ch   = toChannelType(comp);
00503       const int shiftHor     = ( ( ch == CH_L ) ? 0 : m_shiftHor );
00504       const int shiftVer     = ( ( ch == CH_L ) ? 0 : m_shiftVer );
00505       const int ctuXOff      = currTU.block(comp).x - ( m_ctuXLumaSamples >> shiftHor ); // x offset from left edge of CTU in respective channel sample units
00506       const int ctuYOff      = currTU.block(comp).y - ( m_ctuYLumaSamples >> shiftVer ); // y offset from top edge of CTU in respective channel sample units
00507       const int minCUWidth   = cu.cs->pcv->minCUWidth >> shiftHor;
00508       if ( currTU.block(comp).valid() && ( ( currTU.block(comp).y == cu.block(comp).y ) ? m_stLFCUParam.topEdge : m_stLFCUParam.internalEdge ) ) // Edge deblocking needs to be recomputed since ISP contains whole CU chroma transforms in last TU of the CU
00509       {
00510         for ( int x = 0; x < currTU.blocks[cIdx].width; x += minCUWidth )
00511         {
00512           const Position  posQ     = Position( currTU.blocks[ch].x + x, currTU.blocks[ch].y );
00513           const Position  posP     = posQ.offset( 0, -1 );
00514           const int sizeQSide      = tuQ.block(comp).height;
00515           const TransformUnit& tuP = *cu.cs->getTU( posP, ch );
00516           const int sizePSide      = tuP.block(comp).height;
00517           m_transformEdge[cIdx][ctuXOff+x][ctuYOff] = true;
00518 
00519           if ( comp == COMPONENT_Y )
00520           {
00521             bool smallBlock = (sizePSide <= 4) || (sizeQSide <= 4);
00522             if (smallBlock)
00523             {
00524               m_maxFilterLengthQ[cIdx][ctuXOff + x][ctuYOff] = 1;
00525               m_maxFilterLengthP[cIdx][ctuXOff + x][ctuYOff] = 1;
00526             }
00527             else
00528             {
00529               m_maxFilterLengthQ[cIdx][ctuXOff + x][ctuYOff] = (sizeQSide >= 32) ? 7 : 3;
00530               m_maxFilterLengthP[cIdx][ctuXOff + x][ctuYOff] = (sizePSide >= 32) ? 7 : 3;
00531             }
00532           }
00533           else
00534           {
00535             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff] = ( sizeQSide >= 8 && sizePSide >= 8 ) ? 3 : 1;
00536             m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff] = ( sizeQSide >= 8 && sizePSide >= 8 ) ? 3 : 1;
00537           }
00538         }
00539       }
00540     }
00541   }
00542   if ( edgeDir == EDGE_VER )
00543   {
00544     for ( int cIdx = firstComponent; cIdx < ::getNumberValidComponents(tuQ.chromaFormat); cIdx++ ) // per component
00545     {
00546       const ComponentID comp = ComponentID(cIdx);
00547       const ChannelType ch   = toChannelType(comp);
00548       const int shiftHor     = ( ( ch == CH_L ) ? 0 : m_shiftHor );
00549       const int shiftVer     = ( ( ch == CH_L ) ? 0 : m_shiftVer );
00550       const int ctuXOff      = currTU.block(comp).x - ( m_ctuXLumaSamples >> shiftHor ); // x offset from left edge of CTU in respective channel sample units
00551       const int ctuYOff      = currTU.block(comp).y - ( m_ctuYLumaSamples >> shiftVer ); // y offset from top edge of CTU in respective channel sample units
00552       const int minCUHeight  = cu.cs->pcv->minCUHeight >> shiftVer;
00553       if ( currTU.block(comp).valid() && ( ( currTU.block(comp).x == cu.block(comp).x ) ? m_stLFCUParam.leftEdge : m_stLFCUParam.internalEdge ) ) // Edge deblocking needs to be recomputed since ISP contains whole CU chroma transforms in last TU of the CU
00554       {
00555         for ( int y = 0; y < currTU.blocks[cIdx].height; y += minCUHeight )
00556         {
00557           const Position  posQ     = Position( currTU.blocks[ch].x, currTU.blocks[ch].y + y );
00558           const Position  posP     = posQ.offset( -1, 0 );
00559           const int sizeQSide      = tuQ.block(comp).width;
00560           const TransformUnit& tuP = *cu.cs->getTU( posP, ch );
00561           const int sizePSide      = tuP.block(comp).width;
00562           m_transformEdge[cIdx][ctuXOff][ctuYOff+y] = true;
00563 
00564           if ( comp == COMPONENT_Y )
00565           {
00566             bool smallBlock = (sizePSide <= 4) || (sizeQSide <= 4);
00567             if (smallBlock)
00568             {
00569               m_maxFilterLengthQ[cIdx][ctuXOff][ctuYOff + y] = 1;
00570               m_maxFilterLengthP[cIdx][ctuXOff][ctuYOff + y] = 1;
00571             }
00572             else
00573             {
00574               m_maxFilterLengthQ[cIdx][ctuXOff][ctuYOff + y] = (sizeQSide >= 32) ? 7 : 3;
00575               m_maxFilterLengthP[cIdx][ctuXOff][ctuYOff + y] = (sizePSide >= 32) ? 7 : 3;
00576             }
00577           }
00578           else
00579           {
00580             m_maxFilterLengthQ[cIdx][ctuXOff][ctuYOff+y] = ( sizeQSide >= 8 && sizePSide >= 8 ) ? 3 : 1;
00581             m_maxFilterLengthP[cIdx][ctuXOff][ctuYOff+y] = ( sizeQSide >= 8 && sizePSide >= 8 ) ? 3 : 1;
00582           }
00583         }
00584       }
00585     }
00586   }
00587 }
00588 
00589 void LoopFilter::xSetMaxFilterLengthPQForCodingSubBlocks( const DeblockEdgeDir edgeDir, const CodingUnit& cu, const PredictionUnit& currPU, const bool& mvSubBlocks, const int& subBlockSize, const Area& areaPu )
00590 {
00591   if ( mvSubBlocks && currPU.Y().valid() )
00592   {
00593     const int cIdx         = 0;
00594     const ComponentID comp = ComponentID(cIdx);
00595     const int ctuYOff      = currPU.block(comp).y - m_ctuYLumaSamples; // y offset from top edge of CTU in luma samples
00596     const int ctuXOff      = currPU.block(comp).x - m_ctuXLumaSamples; // x offset from left edge of CTU in luma samples
00597     const int minCUWidth   = cu.cs->pcv->minCUWidth;
00598     const int minCUHeight  = cu.cs->pcv->minCUHeight;
00599     if ( edgeDir == EDGE_HOR )
00600     {
00601       for ( int y = 0; y < areaPu.height; y += subBlockSize )
00602       {
00603         for ( int x = 0; x < areaPu.width; x += minCUWidth )
00604         {
00605           if ( m_transformEdge[cIdx][ctuXOff+x][ctuYOff+y] )
00606           {
00607             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y] = std::min<int>(m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y], 5);
00608             if ( y > 0 )
00609             {
00610               m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y] = std::min<int>(m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y], 5);
00611             }
00612           }
00613           else if (y > 0 && (m_transformEdge[cIdx][ctuXOff + x][ctuYOff + y - 4] || ((y + 4) >= areaPu.height) || m_transformEdge[cIdx][ctuXOff + x][ctuYOff + y + 4])) // adjacent to transform edge  +/- 4
00614           {
00615             m_maxFilterLengthQ[cIdx][ctuXOff + x][ctuYOff + y] = 1;
00616             m_maxFilterLengthP[cIdx][ctuXOff + x][ctuYOff + y] = 1;
00617           }
00618           else if (y > 0 && ( ( y == 8 ) || m_transformEdge[cIdx][ctuXOff+x][ctuYOff+y-8] || (( y + 8 ) >= areaPu.height) || m_transformEdge[cIdx][ctuXOff+x][ctuYOff+y+8] )) // adjacent to transform edge on 8x8 grid
00619           {
00620             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y] = 2;
00621             m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y] = 2;
00622           }
00623           else
00624           {
00625             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y] = 3;
00626             m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y] = 3;
00627           }
00628         }
00629       }
00630     }
00631     else // edgeDir == EDGE_VER
00632     {
00633       for ( int x = 0; x < areaPu.width; x += subBlockSize )
00634       {
00635         for ( int y = 0; y < areaPu.height; y += minCUHeight )
00636         {
00637           if ( m_transformEdge[cIdx][ctuXOff+x][ctuYOff+y] )
00638           {
00639             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y] = std::min<int>(m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y], 5);
00640             if ( x > 0 )
00641             {
00642               m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y] = std::min<int>(m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y], 5);
00643             }
00644           }
00645           else if (x > 0 && (m_transformEdge[cIdx][ctuXOff + x - 4][ctuYOff + y] || ((x + 4) >= areaPu.width) || m_transformEdge[cIdx][ctuXOff + x + 4][ctuYOff + y])) // adjacent to transform edge +/- 4
00646           {
00647             m_maxFilterLengthQ[cIdx][ctuXOff + x][ctuYOff + y] = 1;
00648             m_maxFilterLengthP[cIdx][ctuXOff + x][ctuYOff + y] = 1;
00649           }
00650           else if ( x > 0 && ( ( x == 8 ) || m_transformEdge[cIdx][ctuXOff+x-8][ctuYOff+y] || ( (x + 8) >= areaPu.width ) || m_transformEdge[cIdx][ctuXOff+x+8][ctuYOff+y] ) ) // adjacent to transform edge on 8x8 grid
00651           {
00652             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y] = 2;
00653             m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y] = 2;
00654           }
00655           else
00656           {
00657             m_maxFilterLengthQ[cIdx][ctuXOff+x][ctuYOff+y] = 3;
00658             m_maxFilterLengthP[cIdx][ctuXOff+x][ctuYOff+y] = 3;
00659           }
00660         }
00661       }
00662     }
00663   }
00664 }
00665 
00666 void LoopFilter::xSetEdgefilterMultiple( const CodingUnit&    cu,
00667                                          const DeblockEdgeDir edgeDir,
00668                                          const Area&          area,
00669                                          const bool           bValue,
00670                                          const bool           EdgeIdx )
00671 {
00672   const PreCalcValues& pcv = *cu.cs->pcv;
00673 
00674   const unsigned uiAdd     = ( edgeDir == EDGE_VER ) ? pcv.partsInCtuWidth : 1;
00675   const unsigned uiNumElem = ( edgeDir == EDGE_VER ) ? ( area.height / pcv.minCUHeight ) : ( area.width / pcv.minCUWidth );
00676   unsigned uiBsIdx         = getRasterIdx( area, pcv );
00677 
00678   for( int ui = 0; ui < uiNumElem; ui++ )
00679   {
00680     m_aapbEdgeFilter[edgeDir][uiBsIdx] = bValue;
00681     if ( m_aapucBS[edgeDir][uiBsIdx] && bValue )
00682     {
00683       m_aapucBS[edgeDir][uiBsIdx] = 3;  // both the TU and PU edge
00684     }
00685     else
00686     {
00687       if( ! EdgeIdx )
00688       {
00689         m_aapucBS[edgeDir][uiBsIdx] = bValue;
00690       }
00691     }
00692     uiBsIdx += uiAdd;
00693   }
00694 }
