00696 void LoopFilter::xSetLoopfilterParam( const CodingUnit& cu )
00697 {
00698   const Slice& slice = *cu.slice;
00699   const PPS&   pps   = *cu.cs->pps;
00700 
00701   if( slice.getDeblockingFilterDisable() )
00702   {
00703     m_stLFCUParam.leftEdge = m_stLFCUParam.topEdge = m_stLFCUParam.internalEdge = false;
00704     return;
00705   }
00706 
00707   const Position& pos = cu.blocks[cu.chType].pos();
00708 
00709   m_stLFCUParam.internalEdge = true;
00710 
00711   m_stLFCUParam.leftEdge = (0 < pos.x) && isAvailableLeft(cu, *cu.cs->getCU(pos.offset(-1, 0), cu.chType), !pps.getLoopFilterAcrossSlicesEnabledFlag(), !pps.getLoopFilterAcrossTilesEnabledFlag(),
00712     !( pps.getSubPicFromCU(cu).getloopFilterAcrossEnabledFlag() && pps.getSubPicFromCU(*cu.cs->getCU(pos.offset(-1, 0), cu.chType)).getloopFilterAcrossEnabledFlag()));
00713   m_stLFCUParam.topEdge = (0 < pos.y) && isAvailableAbove(cu, *cu.cs->getCU(pos.offset(0, -1), cu.chType), !pps.getLoopFilterAcrossSlicesEnabledFlag(), !pps.getLoopFilterAcrossTilesEnabledFlag(),
00714     !( pps.getSubPicFromCU(cu).getloopFilterAcrossEnabledFlag() && pps.getSubPicFromCU(*cu.cs->getCU(pos.offset(0, -1), cu.chType)).getloopFilterAcrossEnabledFlag()));
00715 }
00716 
00717 unsigned LoopFilter::xGetBoundaryStrengthSingle ( const CodingUnit& cu, const DeblockEdgeDir edgeDir, const Position& localPos, const ChannelType chType ) const
00718 {
00719   // The boundary strength that is output by the function xGetBoundaryStrengthSingle is a multi component boundary strength that contains boundary strength for luma (bits 0 to 1), cb (bits 2 to 3) and cr (bits 4 to 5).
00720 
00721   const Slice& sliceQ = *cu.slice;
00722 
00723   int shiftHor = cu.Y().valid() ? 0 : ::getComponentScaleX(COMPONENT_Cb, cu.firstPU->chromaFormat);
00724   int shiftVer = cu.Y().valid() ? 0 : ::getComponentScaleY(COMPONENT_Cb, cu.firstPU->chromaFormat);
00725   const Position& posQ = Position{ localPos.x >> shiftHor,  localPos.y >> shiftVer };
00726   const Position  posP  = ( edgeDir == EDGE_VER ) ? posQ.offset( -1, 0 ) : posQ.offset( 0, -1 );
00727 
00728   const CodingUnit& cuQ = cu;
00729   const CodingUnit& cuP = (chType == CHANNEL_TYPE_CHROMA && cuQ.chType == CHANNEL_TYPE_LUMA) ?
00730                           *cu.cs->getCU(recalcPosition( cu.chromaFormat, CHANNEL_TYPE_LUMA, CHANNEL_TYPE_CHROMA, posP), CHANNEL_TYPE_CHROMA) :
00731                           *cu.cs->getCU( posP, cu.chType );
00732 
00733   //-- Set BS for Intra MB : BS = 4 or 3
00734   if( ( MODE_INTRA == cuP.predMode ) || ( MODE_INTRA == cuQ.predMode ) )
00735   {
00736     if( chType == CHANNEL_TYPE_LUMA )
00737     {
00738       int bsY = (MODE_INTRA == cuP.predMode && cuP.bdpcmMode) && (MODE_INTRA == cuQ.predMode && cuQ.bdpcmMode) ? 0 : 2;
00739       return BsSet(bsY, COMPONENT_Y);
00740     }
00741     else
00742     {
00743       int bsC = (MODE_INTRA == cuP.predMode && cuP.bdpcmModeChroma) && (MODE_INTRA == cuQ.predMode && cuQ.bdpcmModeChroma) ? 0 : 2;
00744       return (BsSet(bsC, COMPONENT_Cb) + BsSet(bsC, COMPONENT_Cr));
00745     }
00746   }
00747 
00748   const TransformUnit& tuQ = *cuQ.cs->getTU(posQ, cuQ.chType);
00749   const TransformUnit& tuP = (cuP.chType == CHANNEL_TYPE_CHROMA && cuQ.chType == CHANNEL_TYPE_LUMA) ?
00750                              *cuP.cs->getTU(recalcPosition( cu.chromaFormat, CHANNEL_TYPE_LUMA, CHANNEL_TYPE_CHROMA, posP), CHANNEL_TYPE_CHROMA) :
00751                              *cuP.cs->getTU(posP, cuQ.chType);
00752 
00753   const PreCalcValues& pcv = *cu.cs->pcv;
00754   const unsigned rasterIdx = getRasterIdx( Position{ localPos.x,  localPos.y }, pcv );
00755   if (m_aapucBS[edgeDir][rasterIdx] && (cuP.firstPU->ciipFlag || cuQ.firstPU->ciipFlag))
00756   {
00757     if(chType == CHANNEL_TYPE_LUMA)
00758     {
00759       return BsSet(2, COMPONENT_Y);
00760     }
00761     else
00762     {
00763       return BsSet(2, COMPONENT_Cb) + BsSet(2, COMPONENT_Cr);
00764     }
00765   }
00766 
00767   unsigned tmpBs = 0;
00768   //-- Set BS for not Intra MB : BS = 2 or 1 or 0
00769   if(chType == CHANNEL_TYPE_LUMA)
00770   {
00771     // Y
00772     if (m_aapucBS[edgeDir][rasterIdx] && (TU::getCbf(tuQ, COMPONENT_Y) || TU::getCbf(tuP, COMPONENT_Y)))
00773     {
00774       tmpBs += BsSet(1, COMPONENT_Y);
00775     }
00776   }
00777   else
00778   {
00779     if (pcv.chrFormat != CHROMA_400)
00780     {
00781       // U
00782       if (m_aapucBS[edgeDir][rasterIdx]
00783           && (TU::getCbf(tuQ, COMPONENT_Cb) || TU::getCbf(tuP, COMPONENT_Cb) || tuQ.jointCbCr || tuP.jointCbCr))
00784       {
00785         tmpBs += BsSet(1, COMPONENT_Cb);
00786       }
00787       // V
00788       if (m_aapucBS[edgeDir][rasterIdx]
00789           && (TU::getCbf(tuQ, COMPONENT_Cr) || TU::getCbf(tuP, COMPONENT_Cr) || tuQ.jointCbCr || tuP.jointCbCr))
00790       {
00791         tmpBs += BsSet(1, COMPONENT_Cr);
00792       }
00793     }
00794   }
00795   if (BsGet(tmpBs, COMPONENT_Y) == 1)
00796   {
00797     return tmpBs;
00798   }
00799 
00800   if ( !cu.Y().valid() )
00801   {
00802     return tmpBs;
00803   }
00804 
00805   // and now the pred
00806   if (m_aapucBS[edgeDir][rasterIdx] != 0 && m_aapucBS[edgeDir][rasterIdx] != 3)
00807   {
00808     return tmpBs;
00809   }
00810   if( chType == CHANNEL_TYPE_CHROMA )
00811   {
00812     return tmpBs;
00813   }
00814   if( cuP.predMode != cuQ.predMode && chType == CHANNEL_TYPE_LUMA )
00815   {
00816     return BsSet(1, COMPONENT_Y);
00817   }
00818   const Position& lumaPosQ  = Position{ localPos.x,  localPos.y };
00819   const Position  lumaPosP  = ( edgeDir == EDGE_VER ) ? lumaPosQ.offset( -1, 0 ) : lumaPosQ.offset( 0, -1 );
00820   const MotionInfo&     miQ = cuQ.cs->getMotionInfo( lumaPosQ );
00821   const MotionInfo&     miP = cuP.cs->getMotionInfo( lumaPosP );
00822   const Slice&       sliceP = *cuP.slice;
00823 
00824   if (sliceQ.isInterB() || sliceP.isInterB())
00825   {
00826     const Picture *piRefP0 = (CU::isIBC(cuP) ? sliceP.getPic() : ((0 > miP.refIdx[0]) ? NULL : sliceP.getRefPic(REF_PIC_LIST_0, miP.refIdx[0])));
00827     const Picture *piRefP1 = (CU::isIBC(cuP) ? NULL            : ((0 > miP.refIdx[1]) ? NULL : sliceP.getRefPic(REF_PIC_LIST_1, miP.refIdx[1])));
00828     const Picture *piRefQ0 = (CU::isIBC(cuQ) ? sliceQ.getPic() : ((0 > miQ.refIdx[0]) ? NULL : sliceQ.getRefPic(REF_PIC_LIST_0, miQ.refIdx[0])));
00829     const Picture *piRefQ1 = (CU::isIBC(cuQ) ? NULL            : ((0 > miQ.refIdx[1]) ? NULL : sliceQ.getRefPic(REF_PIC_LIST_1, miQ.refIdx[1])));
00830     Mv mvP0, mvP1, mvQ0, mvQ1;
00831 
00832     if (0 <= miP.refIdx[0])
00833     {
00834       mvP0 = miP.mv[0];
00835     }
00836     if (0 <= miP.refIdx[1])
00837     {
00838       mvP1 = miP.mv[1];
00839     }
00840     if (0 <= miQ.refIdx[0])
00841     {
00842       mvQ0 = miQ.mv[0];
00843     }
00844     if (0 <= miQ.refIdx[1])
00845     {
00846       mvQ1 = miQ.mv[1];
00847     }
00848 
00849     int nThreshold = (1 << MV_FRACTIONAL_BITS_INTERNAL) >> 1;
00850     unsigned uiBs = 0;
00851 
00852     //th can be optimized
00853     if ( ((piRefP0==piRefQ0)&&(piRefP1==piRefQ1)) || ((piRefP0==piRefQ1)&&(piRefP1==piRefQ0)) )
00854     {
00855       if ( piRefP0 != piRefP1 )   // Different L0 & L1
00856       {
00857         if ( piRefP0 == piRefQ0 )
00858         {
00859           uiBs  = ((abs(mvQ0.getHor() - mvP0.getHor()) >= nThreshold) || (abs(mvQ0.getVer() - mvP0.getVer()) >= nThreshold) ||
00860                    (abs(mvQ1.getHor() - mvP1.getHor()) >= nThreshold) || (abs(mvQ1.getVer() - mvP1.getVer()) >= nThreshold))
00861                   ? 1 : 0;
00862         }
00863         else
00864         {
00865           uiBs  = ((abs(mvQ1.getHor() - mvP0.getHor()) >= nThreshold) || (abs(mvQ1.getVer() - mvP0.getVer()) >= nThreshold) ||
00866                    (abs(mvQ0.getHor() - mvP1.getHor()) >= nThreshold) || (abs(mvQ0.getVer() - mvP1.getVer()) >= nThreshold))
00867                   ? 1 : 0;
00868         }
00869       }
00870       else    // Same L0 & L1
00871       {
00872         uiBs  = ((abs(mvQ0.getHor() - mvP0.getHor()) >= nThreshold) || (abs(mvQ0.getVer() - mvP0.getVer()) >= nThreshold) ||
00873                  (abs(mvQ1.getHor() - mvP1.getHor()) >= nThreshold) || (abs(mvQ1.getVer() - mvP1.getVer()) >= nThreshold))
00874               &&
00875                 ((abs(mvQ1.getHor() - mvP0.getHor()) >= nThreshold) || (abs(mvQ1.getVer() - mvP0.getVer()) >= nThreshold) ||
00876                  (abs(mvQ0.getHor() - mvP1.getHor()) >= nThreshold) || (abs(mvQ0.getVer() - mvP1.getVer()) >= nThreshold))
00877               ? 1 : 0;
00878       }
00879     }
00880     else // for all different Ref_Idx
00881     {
00882       uiBs = 1;
00883     }
00884     return uiBs + tmpBs;
00885   }
00886 
00887 
00888   // pcSlice->isInterP()
00889   CHECK(CU::isInter(cuP) && 0 > miP.refIdx[0], "Invalid reference picture list index");
00890   CHECK(CU::isInter(cuP) && 0 > miQ.refIdx[0], "Invalid reference picture list index");
00891   const Picture *piRefP0 = (CU::isIBC(cuP) ? sliceP.getPic() : sliceP.getRefPic(REF_PIC_LIST_0, miP.refIdx[0]));
00892   const Picture *piRefQ0 = (CU::isIBC(cuQ) ? sliceQ.getPic() : sliceQ.getRefPic(REF_PIC_LIST_0, miQ.refIdx[0]));
00893   if (piRefP0 != piRefQ0)
00894   {
00895     return tmpBs + 1;
00896   }
00897 
00898   Mv mvP0 = miP.mv[0];
00899   Mv mvQ0 = miQ.mv[0];
00900 
00901   int nThreshold = (1 << MV_FRACTIONAL_BITS_INTERNAL) >> 1;
00902   return ( ( abs( mvQ0.getHor() - mvP0.getHor() ) >= nThreshold ) || ( abs( mvQ0.getVer() - mvP0.getVer() ) >= nThreshold ) ) ? (tmpBs + 1) : tmpBs;
00903 }
00904 
00905 #if LUMA_ADAPTIVE_DEBLOCKING_FILTER_QP_OFFSET
00906 void LoopFilter::deriveLADFShift( const Pel* src, const int stride, int& shift, const DeblockEdgeDir edgeDir, const SPS sps )
00907 {
00908   uint32_t lumaLevel = 0;
00909   shift = sps.getLadfQpOffset(0);
00910 
00911   if (edgeDir == EDGE_VER)
00912   {
00913     lumaLevel = (src[0] + src[3*stride] + src[-1] + src[3*stride - 1]) >> 2;
00914   }
00915   else // (edgeDir == EDGE_HOR)
00916   {
00917     lumaLevel = (src[0] + src[3] + src[-stride] + src[-stride + 3]) >> 2;
00918   }
00919 
00920   for ( int k = 1; k < sps.getLadfNumIntervals(); k++ )
00921   {
00922     const int th = sps.getLadfIntervalLowerBound( k );
00923     if ( lumaLevel > th )
00924     {
00925       shift = sps.getLadfQpOffset( k );
00926     }
00927     else
00928     {
00929       break;
00930     }
00931   }
00932 }
00933 #endif
00934 
00935 void LoopFilter::xEdgeFilterLuma( const CodingUnit& cu, const DeblockEdgeDir edgeDir, const int iEdge )
00936 {
00937   const CompArea&  lumaArea = cu.block(COMPONENT_Y);
00938   const PreCalcValues& pcv = *cu.cs->pcv;
00939 
00940   PelBuf        picYuvRec = m_enc ? m_encPicYuvBuffer.getBuf( lumaArea ) : cu.cs->getRecoBuf( lumaArea );
00941   Pel           *piSrc    = picYuvRec.buf;
00942   const int     iStride   = picYuvRec.stride;
00943   Pel           *piTmpSrc = piSrc;
00944   const PPS     &pps      = *(cu.cs->pps);
00945   const SPS     &sps      = *(cu.cs->sps);
00946   const Slice   &slice    = *(cu.slice);
00947   const bool    spsPaletteEnabledFlag          = sps.getPLTMode();
00948   const int     bitDepthLuma                   = sps.getBitDepth(CHANNEL_TYPE_LUMA);
00949   const ClpRng& clpRng( cu.cs->slice->clpRng(COMPONENT_Y) );
00950 
00951   int          iQP          = 0;
00952   unsigned     uiNumParts   = ( ( ( edgeDir == EDGE_VER ) ? lumaArea.height / pcv.minCUHeight : lumaArea.width / pcv.minCUWidth ) );
00953   int          pelsInPart   = pcv.minCUWidth;
00954   unsigned     uiBsAbsIdx   = 0, uiBs = 0;
00955   int          iOffset, iSrcStep;
00956 
00957   bool  bPartPNoFilter  = false;
00958   bool  bPartQNoFilter  = false;
00959   int   betaOffsetDiv2  = slice.getDeblockingFilterBetaOffsetDiv2();
00960   int   tcOffsetDiv2    = slice.getDeblockingFilterTcOffsetDiv2();
00961   int   xoffset, yoffset;
00962 
00963   Position pos;
00964 
00965   if (edgeDir == EDGE_VER)
00966   {
00967     xoffset   = 0;
00968     yoffset   = pelsInPart;
00969     iOffset   = 1;
00970     iSrcStep  = iStride;
00971     piTmpSrc += iEdge * pelsInPart;
00972     pos       = Position{ lumaArea.x + iEdge * pelsInPart, lumaArea.y - yoffset };
00973   }
00974   else  // (edgeDir == EDGE_HOR)
00975   {
00976     xoffset   = pelsInPart;
00977     yoffset   = 0;
00978     iOffset   = iStride;
00979     iSrcStep  = 1;
00980     piTmpSrc += iEdge*pelsInPart*iStride;
00981     pos       = Position{ lumaArea.x - xoffset, lumaArea.y + iEdge * pelsInPart };
00982   }
00983 
00984   const int iBitdepthScale = 1 << (bitDepthLuma - 8);
00985 
00986   // dec pos since within the loop we first calc the pos
00987   for( int iIdx = 0; iIdx < uiNumParts; iIdx++ )
00988   {
00989     pos.x += xoffset;
00990     pos.y += yoffset;
00991 
00992     // Deblock luma boundaries on 4x4 grid only
00993     if (edgeDir == EDGE_HOR && (pos.y % 4) != 0)
00994     {
00995       continue;
00996     }
00997     if (edgeDir == EDGE_VER && (pos.x % 4) != 0)
00998     {
00999       continue;
01000     }
01001     uiBsAbsIdx = getRasterIdx( pos, pcv );
01002     uiBs = BsGet(m_aapucBS[edgeDir][uiBsAbsIdx], COMPONENT_Y);
01003 
01004     if( uiBs )
01005     {
01006       const CodingUnit& cuQ =  cu;
01007       const CodingUnit& cuP = *cu.cs->getCU(pos.offset(xoffset - pelsInPart, yoffset - pelsInPart), cu.chType);
01008       // Derive neighboring PU index
01009       if (edgeDir == EDGE_VER)
01010       {
01011         if (!isAvailableLeft(cu, cuP, !pps.getLoopFilterAcrossSlicesEnabledFlag(), !pps.getLoopFilterAcrossTilesEnabledFlag(),
01012           !( pps.getSubPicFromCU(cu).getloopFilterAcrossEnabledFlag() && pps.getSubPicFromCU(cuP).getloopFilterAcrossEnabledFlag())))
01013         {
01014           m_aapucBS[edgeDir][uiBsAbsIdx] = uiBs = 0;
01015           continue;
01016         }
01017       }
01018       else  // (iDir == EDGE_HOR)
01019       {
01020         if (!isAvailableAbove(cu, cuP, !pps.getLoopFilterAcrossSlicesEnabledFlag(), !pps.getLoopFilterAcrossTilesEnabledFlag(),
01021           !( pps.getSubPicFromCU(cu).getloopFilterAcrossEnabledFlag() && pps.getSubPicFromCU(cuP).getloopFilterAcrossEnabledFlag())))
01022         {
01023           m_aapucBS[edgeDir][uiBsAbsIdx] = uiBs = 0;
01024           continue;
01025         }
01026       }
01027 
01028       iQP = (cuP.qp + cuQ.qp + 1) >> 1;
01029 
01030 #if LUMA_ADAPTIVE_DEBLOCKING_FILTER_QP_OFFSET
01031       if ( sps.getLadfEnabled() )
01032       {
01033         int iShift = 0;
01034         deriveLADFShift( piTmpSrc + iSrcStep * (iIdx*pelsInPart), iStride, iShift, edgeDir, sps );
01035         iQP += iShift;
01036       }
01037 #endif
01038 
01039       bool sidePisLarge   = false;
01040       bool sideQisLarge   = false;
01041       int maxFilterLengthP = m_maxFilterLengthP[COMPONENT_Y][pos.x-m_ctuXLumaSamples][pos.y-m_ctuYLumaSamples];
01042       int maxFilterLengthQ = m_maxFilterLengthQ[COMPONENT_Y][pos.x-m_ctuXLumaSamples][pos.y-m_ctuYLumaSamples];
01043       if (maxFilterLengthP > 3)
01044       {
01045         sidePisLarge = true;
01046         if ( maxFilterLengthP > 5 )
01047         {
01048           // restrict filter length if sub-blocks are used (e.g affine or ATMVP)
01049           if (cuP.affine)
01050           {
01051             maxFilterLengthP = std::min(maxFilterLengthP, 5);
01052           }
01053         }
01054       }
01055       if (maxFilterLengthQ > 3)
01056       {
01057         sideQisLarge = true;
01058       }
01059 
01060       if (edgeDir == EDGE_HOR && pos.y % slice.getSPS()->getCTUSize() == 0)
01061       {
01062         sidePisLarge = false;
01063       }
01064       const int iIndexTC  = Clip3(0, MAX_QP + DEFAULT_INTRA_TC_OFFSET, int(iQP + DEFAULT_INTRA_TC_OFFSET*(uiBs - 1) + (tcOffsetDiv2 << 1)));
01065       const int iIndexB   = Clip3(0, MAX_QP, iQP + (betaOffsetDiv2 << 1));
01066 
01067       const int iTc = bitDepthLuma < 10 ? ((sm_tcTable[iIndexTC] + (1 << (9 - bitDepthLuma))) >> (10 - bitDepthLuma)) : ((sm_tcTable[iIndexTC]) << (bitDepthLuma - 10));
01068       const int iBeta     = sm_betaTable[iIndexB ] * iBitdepthScale;
01069       const int iSideThreshold = ( iBeta + ( iBeta >> 1 ) ) >> 3;
01070       const int iThrCut   = iTc * 10;
01071 
01072       const unsigned uiBlocksInPart = pelsInPart / 4 ? pelsInPart / 4 : 1;
01073 
01074       for( int iBlkIdx = 0; iBlkIdx < uiBlocksInPart; iBlkIdx++ )
01075       {
01076         const int dp0 = xCalcDP(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 0), iOffset);
01077         const int dq0 = xCalcDQ(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 0), iOffset);
01078         const int dp3 = xCalcDP(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 3), iOffset);
01079         const int dq3 = xCalcDQ(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 3), iOffset);
01080         int dp0L = dp0;
01081         int dq0L = dq0;
01082         int dp3L = dp3;
01083         int dq3L = dq3;
01084 
01085         if (sidePisLarge)
01086         {
01087           dp0L = (dp0L + xCalcDP(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 0) - 3 * iOffset, iOffset) + 1) >> 1;
01088           dp3L = (dp3L + xCalcDP(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 3) - 3 * iOffset, iOffset) + 1) >> 1;
01089         }
01090         if (sideQisLarge)
01091         {
01092           dq0L = (dq0L + xCalcDQ(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 0) + 3 * iOffset, iOffset) + 1) >> 1;
01093           dq3L = (dq3L + xCalcDQ(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + 3) + 3 * iOffset, iOffset) + 1) >> 1;
01094         }
01095         bool useLongtapFilter = false;
01096         if (sidePisLarge || sideQisLarge)
01097         {
01098           int d0L = dp0L + dq0L;
01099           int d3L = dp3L + dq3L;
01100 
01101           int dpL = dp0L + dp3L;
01102           int dqL = dq0L + dq3L;
01103 
01104           int dL = d0L + d3L;
01105 
01106           bPartPNoFilter = bPartQNoFilter = false;
01107           if (spsPaletteEnabledFlag)
01108           {
01109             // check if each of PUs is palette coded
01110             bPartPNoFilter = bPartPNoFilter || CU::isPLT(cuP);
01111             bPartQNoFilter = bPartQNoFilter || CU::isPLT(cuQ);
01112           }
01113 
01114           if (dL < iBeta)
01115           {
01116             const bool filterP = (dpL < iSideThreshold);
01117             const bool filterQ = (dqL < iSideThreshold);
01118 
01119             Pel* src0 = piTmpSrc + iSrcStep * (iIdx*pelsInPart + iBlkIdx * 4 + 0);
01120             Pel* src3 = piTmpSrc + iSrcStep * (iIdx*pelsInPart + iBlkIdx * 4 + 3);
01121 
01122             // adjust decision so that it is not read beyond p5 is maxFilterLengthP is 5 and q5 if maxFilterLengthQ is 5
01123             const bool swL = xUseStrongFiltering(src0, iOffset, 2 * d0L, iBeta, iTc, sidePisLarge, sideQisLarge, maxFilterLengthP, maxFilterLengthQ)
01124               && xUseStrongFiltering(src3, iOffset, 2 * d3L, iBeta, iTc, sidePisLarge, sideQisLarge, maxFilterLengthP, maxFilterLengthQ);
01125             if (swL)
01126             {
01127               useLongtapFilter = true;
01128               for (int i = 0; i < DEBLOCK_SMALLEST_BLOCK / 2; i++)
01129               {
01130                 xPelFilterLuma(piTmpSrc + iSrcStep*(iIdx*pelsInPart + iBlkIdx * 4 + i), iOffset, iTc, swL, bPartPNoFilter, bPartQNoFilter, iThrCut, filterP, filterQ, clpRng, sidePisLarge, sideQisLarge, maxFilterLengthP, maxFilterLengthQ);
01131               }
01132             }
01133 
01134           }
01135         }
01136         if (!useLongtapFilter)
01137         {
01138           const int d0 = dp0 + dq0;
01139           const int d3 = dp3 + dq3;
01140 
01141           const int dp = dp0 + dp3;
01142           const int dq = dq0 + dq3;
01143           const int d  = d0 + d3;
01144 
01145           bPartPNoFilter = bPartQNoFilter = false;
01146           if (spsPaletteEnabledFlag)
01147           {
01148             // check if each of PUs is palette coded
01149             bPartPNoFilter = bPartPNoFilter || CU::isPLT(cuP);
01150             bPartQNoFilter = bPartQNoFilter || CU::isPLT(cuQ);
01151           }
01152 
01153           if (d < iBeta)
01154           {
01155             bool bFilterP = false;
01156             bool bFilterQ = false;
01157             if (maxFilterLengthP > 1 && maxFilterLengthQ > 1)
01158             {
01159               bFilterP = (dp < iSideThreshold);
01160               bFilterQ = (dq < iSideThreshold);
01161             }
01162             bool sw = false;
01163             if (maxFilterLengthP > 2 && maxFilterLengthQ > 2)
01164             {
01165               sw = xUseStrongFiltering(piTmpSrc + iSrcStep * (iIdx * pelsInPart + iBlkIdx * 4 + 0), iOffset, 2 * d0,
01166                                        iBeta, iTc)
01167                    && xUseStrongFiltering(piTmpSrc + iSrcStep * (iIdx * pelsInPart + iBlkIdx * 4 + 3), iOffset, 2 * d3,
01168                                           iBeta, iTc);
01169             }
01170             for (int i = 0; i < DEBLOCK_SMALLEST_BLOCK / 2; i++)
01171             {
01172               xPelFilterLuma(piTmpSrc + iSrcStep * (iIdx * pelsInPart + iBlkIdx * 4 + i), iOffset, iTc, sw,
01173                              bPartPNoFilter, bPartQNoFilter, iThrCut, bFilterP, bFilterQ, clpRng);
01174             }
01175           }
01176         }
01177       }
01178     }
01179   }
01180 }
01181 
01182 
01183 void LoopFilter::xEdgeFilterChroma(const CodingUnit& cu, const DeblockEdgeDir edgeDir, const int iEdge)
01184 {
01185   const Position lumaPos   = cu.Y().valid() ? cu.Y().pos() : recalcPosition( cu.chromaFormat, cu.chType, CHANNEL_TYPE_LUMA, cu.blocks[cu.chType].pos() );
01186   const Size     lumaSize  = cu.Y().valid() ? cu.Y().size() : recalcSize( cu.chromaFormat, cu.chType, CHANNEL_TYPE_LUMA, cu.blocks[cu.chType].size() );
01187 
01188   const PreCalcValues& pcv = *cu.cs->pcv;
01189   unsigned  rasterIdx      = getRasterIdx( lumaPos, pcv );
01190   PelBuf     picYuvRecCb = m_enc ? m_encPicYuvBuffer.getBuf(cu.block(COMPONENT_Cb)) : cu.cs->getRecoBuf(cu.block(COMPONENT_Cb));
01191   PelBuf     picYuvRecCr = m_enc ? m_encPicYuvBuffer.getBuf(cu.block(COMPONENT_Cr)) : cu.cs->getRecoBuf(cu.block(COMPONENT_Cr));
01192   Pel       *piSrcCb       = picYuvRecCb.buf;
01193   Pel       *piSrcCr       = picYuvRecCr.buf;
01194   const int  iStride       = picYuvRecCb.stride;
01195   const SPS &sps           = *cu.cs->sps;
01196   const PPS &pps           = *cu.cs->pps;
01197   const Slice  &slice      = *cu.slice;
01198   const ChromaFormat nChromaFormat   = sps.getChromaFormatIdc();
01199   const unsigned uiPelsInPartChromaH = pcv.minCUWidth  >> ::getComponentScaleX(COMPONENT_Cb, nChromaFormat);
01200   const unsigned uiPelsInPartChromaV = pcv.minCUHeight >> ::getComponentScaleY(COMPONENT_Cb, nChromaFormat);
01201 
01202   int       iOffset, iSrcStep;
01203   unsigned  uiLoopLength;
01204 
01205   bool      bPartPNoFilter  = false;
01206   bool      bPartQNoFilter  = false;
01207   const int tcOffsetDiv2[2]   = { slice.getDeblockingFilterCbTcOffsetDiv2(), slice.getDeblockingFilterCrTcOffsetDiv2() };
01208   const int betaOffsetDiv2[2] = { slice.getDeblockingFilterCbBetaOffsetDiv2(), slice.getDeblockingFilterCrBetaOffsetDiv2() };
01209 
01210   // Vertical Position
01211   unsigned uiEdgeNumInCtuVert = rasterIdx % pcv.partsInCtuWidth + iEdge;
01212   unsigned uiEdgeNumInCtuHor  = rasterIdx / pcv.partsInCtuWidth + iEdge;
01213 
01214   if( ( uiPelsInPartChromaH < DEBLOCK_SMALLEST_BLOCK ) && ( uiPelsInPartChromaV < DEBLOCK_SMALLEST_BLOCK ) &&
01215       (
01216         ( ( uiEdgeNumInCtuVert % ( DEBLOCK_SMALLEST_BLOCK / uiPelsInPartChromaH ) ) && ( edgeDir == EDGE_VER ) ) ||
01217         ( ( uiEdgeNumInCtuHor  % ( DEBLOCK_SMALLEST_BLOCK / uiPelsInPartChromaV ) ) && ( edgeDir == EDGE_HOR ) )
01218       )
01219     )
01220   {
01221     return;
01222   }
01223 
01224   unsigned uiNumParts =  ( edgeDir == EDGE_VER ) ? lumaSize.height / pcv.minCUHeight : lumaSize.width / pcv.minCUWidth ;
01225   int   uiNumPelsLuma = pcv.minCUWidth;
01226   unsigned uiBsAbsIdx;
01227   unsigned bS[2];
01228 
01229   Pel* piTmpSrcCb = piSrcCb;
01230   Pel* piTmpSrcCr = piSrcCr;
01231   int xoffset, yoffset;
01232   Position pos( lumaPos.x, lumaPos.y );
01233 
01234   if( edgeDir == EDGE_VER )
01235   {
01236     xoffset      = 0;
01237     yoffset      = uiNumPelsLuma;
01238     iOffset      = 1;
01239     iSrcStep     = iStride;
01240     piTmpSrcCb  += iEdge*uiPelsInPartChromaH;
01241     piTmpSrcCr  += iEdge*uiPelsInPartChromaH;
01242     uiLoopLength = uiPelsInPartChromaV;
01243     pos          = Position{ lumaPos.x + iEdge*uiNumPelsLuma, lumaPos.y - yoffset };
01244   }
01245   else  // (edgeDir == EDGE_HOR)
01246   {
01247     xoffset      = uiNumPelsLuma;
01248     yoffset      = 0;
01249     iOffset      = iStride;
01250     iSrcStep     = 1;
01251     piTmpSrcCb  += iEdge*iStride*uiPelsInPartChromaV;
01252     piTmpSrcCr  += iEdge*iStride*uiPelsInPartChromaV;
01253     uiLoopLength = uiPelsInPartChromaH;
01254     pos          = Position{ lumaPos.x - xoffset, lumaPos.y + iEdge*uiNumPelsLuma };
01255   }
01256 
01257   const int iBitdepthScale = 1 << (sps.getBitDepth(CHANNEL_TYPE_CHROMA) - 8);
01258 
01259   for( int iIdx = 0; iIdx < uiNumParts; iIdx++ )
01260   {
01261     pos.x += xoffset;
01262     pos.y += yoffset;
01263 
01264     uiBsAbsIdx = getRasterIdx( pos, pcv );
01265     unsigned tmpBs = m_aapucBS[edgeDir][uiBsAbsIdx];
01266 
01267     tmpBs = m_aapucBS[edgeDir][uiBsAbsIdx];
01268     bS[0] = BsGet(tmpBs, COMPONENT_Cb);
01269     bS[1] = BsGet(tmpBs, COMPONENT_Cr);
01270 
01271     if (bS[0] > 0 || bS[1] > 0)
01272     {
01273       const CodingUnit& cuQ =  cu;
01274       CodingUnit& cuP1 = *cu.cs->getCU( recalcPosition( cu.chromaFormat, CHANNEL_TYPE_LUMA, cu.chType, pos.offset( xoffset - uiNumPelsLuma, yoffset - uiNumPelsLuma ) ), cu.chType );
01275       CodingUnit& cuP  = *cu.cs->getCU( recalcPosition( cu.chromaFormat, CHANNEL_TYPE_LUMA, (cuP1.isSepTree() ? CHANNEL_TYPE_CHROMA : cu.chType), pos.offset( xoffset - uiNumPelsLuma, yoffset - uiNumPelsLuma ) ), (cuP1.isSepTree() ? CHANNEL_TYPE_CHROMA : cu.chType));
01276 
01277       if (edgeDir == EDGE_VER)
01278       {
01279         CHECK(!isAvailableLeft(cu, cuP, !pps.getLoopFilterAcrossSlicesEnabledFlag(), !pps.getLoopFilterAcrossTilesEnabledFlag(),
01280           !( pps.getSubPicFromCU(cu).getloopFilterAcrossEnabledFlag() && pps.getSubPicFromCU(cuP).getloopFilterAcrossEnabledFlag())), "Neighbour not available");
01281       }
01282       else  // (iDir == EDGE_HOR)
01283       {
01284         CHECK(!isAvailableAbove(cu, cuP, !pps.getLoopFilterAcrossSlicesEnabledFlag(), !pps.getLoopFilterAcrossTilesEnabledFlag(),
01285           !( pps.getSubPicFromCU(cu).getloopFilterAcrossEnabledFlag() && pps.getSubPicFromCU(cuP).getloopFilterAcrossEnabledFlag())), "Neighbour not available");
01286       }
01287 
01288       bPartPNoFilter = bPartQNoFilter = false;
01289       if ( sps.getPLTMode())
01290       {
01291         // check if each of PUs is palette coded
01292         bPartPNoFilter = bPartPNoFilter || CU::isPLT(cuP);
01293         bPartQNoFilter = bPartQNoFilter || CU::isPLT(cuQ);
01294       }
01295 
01296       const int maxFilterLengthP = m_maxFilterLengthP[COMPONENT_Cb][(pos.x-m_ctuXLumaSamples)>>m_shiftHor][(pos.y-m_ctuYLumaSamples)>>m_shiftVer];
01297       const int maxFilterLengthQ = m_maxFilterLengthQ[COMPONENT_Cb][(pos.x-m_ctuXLumaSamples)>>m_shiftHor][(pos.y-m_ctuYLumaSamples)>>m_shiftVer];
01298       bool largeBoundary         = false;
01299       bool isChromaHorCTBBoundary = false;
01300       if ( maxFilterLengthP >= 3 && maxFilterLengthQ >= 3 )
01301       {
01302         largeBoundary = true;
01303       }
01304 
01305       if (edgeDir == EDGE_HOR && pos.y % cuP.slice->getSPS()->getCTUSize() == 0)
01306       {
01307         isChromaHorCTBBoundary = true;
01308       }
01309 
01310       for( int chromaIdx = 0; chromaIdx < 2; chromaIdx++ )
01311       {
01312         if ((bS[chromaIdx] == 2) || (largeBoundary && (bS[chromaIdx] == 1)))
01313         {
01314           const ClpRng &clpRng(cu.cs->slice->clpRng(ComponentID(chromaIdx + 1)));
01315           Pel *         piTmpSrcChroma = (chromaIdx == 0) ? piTmpSrcCb : piTmpSrcCr;
01316 
01317           const TransformUnit &tuQ = *cuQ.cs->getTU(
01318             recalcPosition(cu.chromaFormat, CHANNEL_TYPE_LUMA, CHANNEL_TYPE_CHROMA, pos), CHANNEL_TYPE_CHROMA);
01319           const TransformUnit &tuP =
01320             *cuP.cs->getTU(recalcPosition(cu.chromaFormat, CHANNEL_TYPE_LUMA, CHANNEL_TYPE_CHROMA,
01321                                           (edgeDir == EDGE_VER) ? pos.offset(-1, 0) : pos.offset(0, -1)),
01322                            CHANNEL_TYPE_CHROMA);
01323 
01324           const QpParam cQP(tuP, ComponentID(chromaIdx + 1), -MAX_INT, false);
01325           const QpParam cQQ(tuQ, ComponentID(chromaIdx + 1), -MAX_INT, false);
01326 
01327           const int qpBdOffset = tuP.cs->sps->getQpBDOffset(toChannelType(ComponentID(chromaIdx + 1)));
01328           int       baseQp_P   = cQP.Qp(0) - qpBdOffset;
01329           int       baseQp_Q   = cQQ.Qp(0) - qpBdOffset;
01330           int       iQP        = ((baseQp_Q + baseQp_P + 1) >> 1);
01331 
01332           const int iIndexTC =
01333             Clip3<int>(0, MAX_QP + DEFAULT_INTRA_TC_OFFSET,
01334                        iQP + DEFAULT_INTRA_TC_OFFSET * (bS[chromaIdx] - 1) + (tcOffsetDiv2[chromaIdx] << 1));
01335           const int bitDepthChroma = sps.getBitDepth(CHANNEL_TYPE_CHROMA);
01336           const int iTc            = bitDepthChroma < 10
01337                             ? ((sm_tcTable[iIndexTC] + (1 << (9 - bitDepthChroma))) >> (10 - bitDepthChroma))
01338                             : ((sm_tcTable[iIndexTC]) << (bitDepthChroma - 10));
01339           bool useLongFilter = false;
01340           if (largeBoundary)
01341           {
01342             const int indexB = Clip3<int>(0, MAX_QP, iQP + (betaOffsetDiv2[chromaIdx] << 1));
01343             const int beta   = sm_betaTable[indexB] * iBitdepthScale;
01344 
01345             const int dp0 =
01346               xCalcDP(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 0), iOffset, isChromaHorCTBBoundary);
01347             const int dq0 = xCalcDQ(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 0), iOffset);
01348 
01349             const int subSamplingShift = (edgeDir == EDGE_VER) ? m_shiftVer : m_shiftHor;
01350 
01351             const int dp3 =
01352               (subSamplingShift == 1)
01353                 ? xCalcDP(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 1), iOffset, isChromaHorCTBBoundary)
01354                 : xCalcDP(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 3), iOffset, isChromaHorCTBBoundary);
01355             const int dq3 = (subSamplingShift == 1)
01356                               ? xCalcDQ(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 1), iOffset)
01357                               : xCalcDQ(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 3), iOffset);
01358 
01359             const int d0 = dp0 + dq0;
01360             const int d3 = dp3 + dq3;
01361             const int d  = d0 + d3;
01362 
01363             if (d < beta)
01364             {
01365               useLongFilter = true;
01366               const bool sw = xUseStrongFiltering(piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + 0), iOffset,
01367                                                   2 * d0, beta, iTc, false, false, 7, 7, isChromaHorCTBBoundary)
01368                               && xUseStrongFiltering(
01369                                 piTmpSrcChroma + iSrcStep * (iIdx * uiLoopLength + ((subSamplingShift == 1) ? 1 : 3)),
01370                                 iOffset, 2 * d3, beta, iTc, false, false, 7, 7, isChromaHorCTBBoundary);
01371 
01372               for (unsigned step = 0; step < uiLoopLength; step++)
01373               {
01374                 xPelFilterChroma(piTmpSrcChroma + iSrcStep * (step + iIdx * uiLoopLength), iOffset, iTc, sw,
01375                                  bPartPNoFilter, bPartQNoFilter, clpRng, largeBoundary, isChromaHorCTBBoundary);
01376               }
01377             }
01378           }
01379           if (!useLongFilter)
01380           {
01381             for (unsigned step = 0; step < uiLoopLength; step++)
01382             {
01383               xPelFilterChroma(piTmpSrcChroma + iSrcStep * (step + iIdx * uiLoopLength), iOffset, iTc, false,
01384                                bPartPNoFilter, bPartQNoFilter, clpRng, largeBoundary, isChromaHorCTBBoundary);
01385             }
01386           }
01387         }
01388       }
01389     }
01390   }
01391 }
01392 
01393 
01394 
01409 inline void LoopFilter::xBilinearFilter(Pel* srcP, Pel* srcQ, int offset, int refMiddle, int refP, int refQ, int numberPSide, int numberQSide, const int* dbCoeffsP, const int* dbCoeffsQ, int tc) const
01410 {
01411   const char tc7[7] = { 6, 5, 4, 3, 2, 1, 1 };
01412   const char tc3[3] = { 6, 4, 2 };
01413 
01414   const char *tcP = (numberPSide == 3) ? tc3 : tc7;
01415   const char *tcQ = (numberQSide == 3) ? tc3 : tc7;
01416 
01417   for (int pos = 0; pos < numberPSide; pos++)
01418   {
01419     int src    = srcP[-offset * pos];
01420     int cvalue = (tc * tcP[pos]) >> 1;
01421     srcP[-offset * pos] =
01422       Clip3(src - cvalue, src + cvalue, ((refMiddle * dbCoeffsP[pos] + refP * (64 - dbCoeffsP[pos]) + 32) >> 6));
01423   }
01424   for (int pos = 0; pos < numberQSide; pos++)
01425   {
01426     int src    = srcQ[offset * pos];
01427     int cvalue = (tc * tcQ[pos]) >> 1;
01428     srcQ[offset * pos] =
01429       Clip3(src - cvalue, src + cvalue, ((refMiddle * dbCoeffsQ[pos] + refQ * (64 - dbCoeffsQ[pos]) + 32) >> 6));
01430   }
01431 }
01432 
01433 inline void LoopFilter::xFilteringPandQ(Pel* src, int offset, int numberPSide, int numberQSide, int tc) const
01434 {
01435   CHECK(numberPSide <= 3 && numberQSide <= 3, "Short filtering in long filtering function");
01436   Pel* srcP = src-offset;
01437   Pel* srcQ = src;
01438 
01439   int refP = 0;
01440   int refQ = 0;
01441   int refMiddle = 0;
01442 
01443   const int dbCoeffs7[7] = { 59, 50, 41,32,23,14,5 };
01444   const int dbCoeffs3[3] = { 53, 32, 11 };
01445   const int dbCoeffs5[5] = { 58, 45, 32,19,6};
01446   const int* dbCoeffsP   = numberPSide == 7 ? dbCoeffs7 : (numberPSide==5) ? dbCoeffs5 : dbCoeffs3;
01447   const int* dbCoeffsQ   = numberQSide == 7 ? dbCoeffs7 : (numberQSide==5) ? dbCoeffs5 : dbCoeffs3;
01448 
01449   switch (numberPSide)
01450   {
01451     case 7: refP = (srcP[-6*offset]   + srcP[-7 * offset] + 1) >> 1; break;
01452     case 3: refP = (srcP[-2 * offset] + srcP[-3 * offset] + 1) >> 1; break;
01453     case 5: refP = (srcP[-4 * offset] + srcP[-5 * offset] + 1) >> 1; break;
01454   }
01455 
01456   switch (numberQSide)
01457   {
01458     case 7: refQ = (srcQ[6 * offset] + srcQ[7 * offset] + 1) >> 1; break;
01459     case 3: refQ = (srcQ[2 * offset] + srcQ[3 * offset] + 1) >> 1; break;
01460     case 5: refQ = (srcQ[4 * offset] + srcQ[5 * offset] + 1) >> 1; break;
01461   }
01462 
01463   if (numberPSide == numberQSide)
01464   {
01465     if (numberPSide == 5)
01466     {
01467       refMiddle = (2 * (srcP[0] + srcQ[0] + srcP[-offset] + srcQ[offset] + srcP[-2 * offset] + srcQ[2 * offset]) + srcP[-3 * offset] + srcQ[3 * offset] + srcP[-4 * offset] + srcQ[4 * offset] + 8) >> 4;
01468     }
01469     else
01470     {
01471       refMiddle = (2 * (srcP[0] + srcQ[0]) + srcP[-offset] + srcQ[offset] + srcP[-2 * offset] + srcQ[2 * offset] + srcP[-3 * offset] + srcQ[3 * offset] + srcP[-4 * offset] + srcQ[4 * offset] + srcP[-5 * offset] + srcQ[5 * offset] + +srcP[-6 * offset] + srcQ[6 * offset] + 8) >> 4;
01472     }
01473   }
01474   else
01475   {
01476     Pel* srcPt = srcP;
01477     Pel* srcQt = srcQ;
01478     int offsetP = -offset;
01479     int offsetQ = offset;
01480 
01481     int newNumberQSide = numberQSide;
01482     int newNumberPSide = numberPSide;
01483     if (numberQSide > numberPSide)
01484     {
01485       std::swap(srcPt, srcQt);
01486       std::swap(offsetP, offsetQ);
01487       newNumberQSide = numberPSide;
01488       newNumberPSide = numberQSide;
01489     }
01490 
01491     if (newNumberPSide == 7 && newNumberQSide == 5)
01492     {
01493       refMiddle = (2 * (srcP[0] + srcQ[0] + srcP[-offset] + srcQ[offset]) + srcP[-2 * offset] + srcQ[2 * offset] + srcP[-3 * offset] + srcQ[3 * offset] + srcP[-4 * offset] + srcQ[4 * offset] + srcP[-5 * offset] + srcQ[5 * offset] + 8) >> 4;
01494     }
01495     else if (newNumberPSide == 7 && newNumberQSide == 3)
01496     {
01497       refMiddle = (2 * (srcPt[0] + srcQt[0]) + srcQt[0] + 2 * (srcQt[offsetQ] + srcQt[2 * offsetQ]) + srcPt[offsetP] + srcQt[offsetQ] + srcPt[2 * offsetP] + srcPt[3 * offsetP] + srcPt[4 * offsetP] + srcPt[5 * offsetP] + srcPt[6 * offsetP] + 8) >> 4;
01498     }
01499     else //if (newNumberPSide == 5 && newNumberQSide == 3)
01500     {
01501       refMiddle = (srcP[0] + srcQ[0] + srcP[-offset] + srcQ[offset] + srcP[-2 * offset] + srcQ[2 * offset] + srcP[-3 * offset] + srcQ[3 * offset] + 4) >> 3;
01502     }
01503   }
01504   xBilinearFilter(srcP,srcQ,offset,refMiddle,refP,refQ,numberPSide,numberQSide,dbCoeffsP,dbCoeffsQ,tc);
01505 }
01506 
01507 inline void LoopFilter::xPelFilterLuma(Pel* piSrc, const int iOffset, const int tc, const bool sw, const bool bPartPNoFilter, const bool bPartQNoFilter, const int iThrCut, const bool bFilterSecondP, const bool bFilterSecondQ, const ClpRng& clpRng, bool sidePisLarge, bool sideQisLarge, int maxFilterLengthP, int maxFilterLengthQ) const
01508 {
01509   int delta;
01510 
01511   const Pel m4  = piSrc[ 0          ];
01512   const Pel m3  = piSrc[-iOffset    ];
01513   const Pel m5  = piSrc[ iOffset    ];
01514   const Pel m2  = piSrc[-iOffset * 2];
01515   const Pel m6  = piSrc[ iOffset * 2];
01516   const Pel m1  = piSrc[-iOffset * 3];
01517   const Pel m7  = piSrc[ iOffset * 3];
01518   const Pel m0  = piSrc[-iOffset * 4];
01519 
01520   const Pel mP1 = piSrc[-iOffset * 5];
01521   const Pel mP2 = piSrc[-iOffset * 6];
01522   const Pel mP3 = piSrc[-iOffset * 7];
01523   const Pel m8  = piSrc[ iOffset * 4];
01524   const Pel m9  = piSrc[ iOffset * 5];
01525   const Pel m10 = piSrc[ iOffset * 6];
01526   const char tc3[3] = { 3, 2, 1};
01527   if (sw)
01528   {
01529     if (sidePisLarge || sideQisLarge)
01530     {
01531       xFilteringPandQ(piSrc, iOffset, sidePisLarge ? maxFilterLengthP : 3, sideQisLarge ? maxFilterLengthQ : 3, tc);
01532     }
01533     else
01534     {
01535       piSrc[-iOffset]     = Clip3(m3 - tc3[0] * tc, m3 + tc3[0] * tc, ((m1 + 2 * m2 + 2 * m3 + 2 * m4 + m5 + 4) >> 3));
01536       piSrc[0]            = Clip3(m4 - tc3[0] * tc, m4 + tc3[0] * tc, ((m2 + 2 * m3 + 2 * m4 + 2 * m5 + m6 + 4) >> 3));
01537       piSrc[-iOffset * 2] = Clip3(m2 - tc3[1] * tc, m2 + tc3[1] * tc, ((m1 + m2 + m3 + m4 + 2) >> 2));
01538       piSrc[iOffset]      = Clip3(m5 - tc3[1] * tc, m5 + tc3[1] * tc, ((m3 + m4 + m5 + m6 + 2) >> 2));
01539       piSrc[-iOffset * 3] = Clip3(m1 - tc3[2] * tc, m1 + tc3[2] * tc, ((2 * m0 + 3 * m1 + m2 + m3 + m4 + 4) >> 3));
01540       piSrc[iOffset * 2]  = Clip3(m6 - tc3[2] * tc, m6 + tc3[2] * tc, ((m3 + m4 + m5 + 3 * m6 + 2 * m7 + 4) >> 3));
01541     }
01542   }
01543   else
01544   {
01545     /* Weak filter */
01546     delta = ( 9 * ( m4 - m3 ) - 3 * ( m5 - m2 ) + 8 ) >> 4;
01547 
01548     if ( abs(delta) < iThrCut )
01549     {
01550       delta = Clip3( -tc, tc, delta );
01551       piSrc[-iOffset] = ClipPel( m3 + delta, clpRng);
01552       piSrc[0]        = ClipPel( m4 - delta, clpRng);
01553 
01554       const int tc2 = tc >> 1;
01555       if( bFilterSecondP )
01556       {
01557         const int delta1 = Clip3( -tc2, tc2, ( ( ( ( m1 + m3 + 1 ) >> 1 ) - m2 + delta ) >> 1 ) );
01558         piSrc[-iOffset * 2] = ClipPel( m2 + delta1, clpRng);
01559       }
01560       if( bFilterSecondQ )
01561       {
01562         const int delta2 = Clip3( -tc2, tc2, ( ( ( ( m6 + m4 + 1 ) >> 1 ) - m5 - delta ) >> 1 ) );
01563         piSrc[iOffset] = ClipPel( m5 + delta2, clpRng);
01564       }
01565     }
01566   }
01567 
01568   if(bPartPNoFilter)
01569   {
01570     piSrc[-iOffset    ] = m3;
01571     piSrc[-iOffset * 2] = m2;
01572     piSrc[-iOffset * 3] = m1;
01573     if (sidePisLarge)
01574     {
01575       piSrc[-iOffset * 4] = m0;
01576       piSrc[-iOffset * 5] = mP1;
01577       piSrc[-iOffset * 6] = mP2;
01578       piSrc[-iOffset * 7] = mP3;
01579     }
01580   }
01581 
01582   if(bPartQNoFilter)
01583   {
01584     piSrc[ 0          ] = m4;
01585     piSrc[ iOffset    ] = m5;
01586     piSrc[ iOffset * 2] = m6;
01587     if (sideQisLarge)
01588     {
01589       piSrc[iOffset * 3] = m7;
01590       piSrc[iOffset * 4] = m8;
01591       piSrc[iOffset * 5] = m9;
01592       piSrc[iOffset * 6] = m10;
01593     }
01594   }
01595 }
01596 
01607 inline void LoopFilter::xPelFilterChroma(Pel* piSrc, const int iOffset, const int tc, const bool sw, const bool bPartPNoFilter, const bool bPartQNoFilter, const ClpRng& clpRng, const bool largeBoundary, const bool isChromaHorCTBBoundary) const
01608 {
01609   int delta;
01610 
01611   const Pel m0 = piSrc[-iOffset * 4];
01612   const Pel m1 = piSrc[-iOffset * 3];
01613   const Pel m2 = piSrc[-iOffset * 2];
01614   const Pel m3 = piSrc[-iOffset];
01615   const Pel m4 = piSrc[0];
01616   const Pel m5 = piSrc[iOffset];
01617   const Pel m6 = piSrc[iOffset * 2];
01618   const Pel m7 = piSrc[iOffset * 3];
01619 
01620   if (sw)
01621   {
01622     if (isChromaHorCTBBoundary)
01623     {
01624       piSrc[-iOffset * 1] = Clip3(m3 - tc, m3 + tc, ((3 * m2 + 2 * m3 + m4 + m5 + m6 + 4) >> 3)); // p0
01625       piSrc[0] = Clip3(m4 - tc, m4 + tc, ((2 * m2 + m3 + 2 * m4 + m5 + m6 + m7 + 4) >> 3)); // q0
01626       piSrc[iOffset * 1] = Clip3(m5 - tc, m5 + tc, ((m2 + m3 + m4 + 2 * m5 + m6 + 2 * m7 + 4) >> 3));  // q1
01627       piSrc[iOffset * 2] = Clip3(m6 - tc, m6 + tc, ((m3 + m4 + m5 + 2 * m6 + 3 * m7 + 4) >> 3));       // q2
01628     }
01629     else
01630     {
01631       piSrc[-iOffset * 3] = Clip3(m1 - tc, m1 + tc, ((3 * m0 + 2 * m1 + m2 + m3 + m4 + 4) >> 3));       // p2
01632       piSrc[-iOffset * 2] = Clip3(m2 - tc, m2 + tc, ((2 * m0 + m1 + 2 * m2 + m3 + m4 + m5 + 4) >> 3));  // p1
01633       piSrc[-iOffset * 1] = Clip3(m3 - tc, m3 + tc, ((m0 + m1 + m2 + 2 * m3 + m4 + m5 + m6 + 4) >> 3)); // p0
01634       piSrc[0] = Clip3(m4 - tc, m4 + tc, ((m1 + m2 + m3 + 2 * m4 + m5 + m6 + m7 + 4) >> 3)); // q0
01635       piSrc[iOffset * 1] = Clip3(m5 - tc, m5 + tc, ((m2 + m3 + m4 + 2 * m5 + m6 + 2 * m7 + 4) >> 3));  // q1
01636       piSrc[iOffset * 2] = Clip3(m6 - tc, m6 + tc, ((m3 + m4 + m5 + 2 * m6 + 3 * m7 + 4) >> 3));       // q2
01637     }
01638   }
01639   else
01640   {
01641     delta           = Clip3(-tc, tc, ((((m4 - m3) << 2) + m2 - m5 + 4) >> 3));
01642     piSrc[-iOffset] = ClipPel(m3 + delta, clpRng);
01643     piSrc[0]        = ClipPel(m4 - delta, clpRng);
01644   }
01645 
01646 
01647   if( bPartPNoFilter )
01648   {
01649     if (largeBoundary)
01650     {
01651       piSrc[-iOffset * 3] = m1; // p2
01652       piSrc[-iOffset * 2] = m2; // p1
01653     }
01654     piSrc[-iOffset] = m3;
01655   }
01656   if( bPartQNoFilter )
01657   {
01658     if (largeBoundary)
01659     {
01660       piSrc[iOffset * 1] = m5; // q1
01661       piSrc[iOffset * 2] = m6; // q2
01662     }
01663     piSrc[ 0      ] = m4;
01664   }
01665 }
01666 
01676 inline bool LoopFilter::xUseStrongFiltering(Pel* piSrc, const int iOffset, const int d, const int beta, const int tc, bool sidePisLarge, bool sideQisLarge, int maxFilterLengthP, int maxFilterLengthQ, bool isChromaHorCTBBoundary) const
01677 {
01678   const Pel m4 = piSrc[ 0          ];
01679   const Pel m3 = piSrc[-iOffset    ];
01680   const Pel m7 = piSrc[ iOffset * 3];
01681   const Pel m0 = piSrc[-iOffset * 4];
01682   const Pel m2 = piSrc[-iOffset * 2];
01683   int       sp3 = abs(m0 - m3);
01684   if (isChromaHorCTBBoundary)
01685   {
01686     sp3 = abs(m2 - m3);
01687   }
01688   int       sq3      = abs(m7 - m4);
01689   const int d_strong = sp3 + sq3;
01690 
01691   if (sidePisLarge || sideQisLarge)
01692   {
01693     Pel mP4;
01694     Pel m11;
01695     if (sidePisLarge)
01696     {
01697       if (maxFilterLengthP == 7)
01698       {
01699         const Pel mP5 = piSrc[-iOffset * 5];
01700         const Pel mP6 = piSrc[-iOffset * 6];
01701         const Pel mP7 = piSrc[-iOffset * 7];;
01702         mP4 = piSrc[-iOffset * 8];
01703         sp3 = sp3 + abs(mP5 - mP6 - mP7 + mP4);
01704       }
01705       else
01706       {
01707         mP4 = piSrc[-iOffset * 6];
01708       }
01709       sp3 = (sp3 + abs(m0 - mP4) + 1) >> 1;
01710     }
01711     if (sideQisLarge)
01712     {
01713       if (maxFilterLengthQ == 7)
01714       {
01715         const Pel m8 = piSrc[iOffset * 4];
01716         const Pel m9 = piSrc[iOffset * 5];
01717         const Pel m10 = piSrc[iOffset * 6];;
01718         m11 = piSrc[iOffset * 7];
01719         sq3 = sq3 + abs(m8 - m9 - m10 + m11);
01720       }
01721       else
01722       {
01723         m11 = piSrc[iOffset * 5];
01724       }
01725       sq3 = (sq3 + abs(m11 - m7) + 1) >> 1;
01726     }
01727     return ((sp3 + sq3) < (beta * 3 >> 5)) && (d < (beta >> 4)) && (abs(m3 - m4) < ((tc * 5 + 1) >> 1));
01728   }
01729   else
01730   {
01731     return ((d_strong < (beta >> 3)) && (d < (beta >> 2)) && (abs(m3 - m4) < ((tc * 5 + 1) >> 1)));
01732   }
01733 }
01734 
01735 inline int LoopFilter::xCalcDP(Pel* piSrc, const int iOffset, const bool isChromaHorCTBBoundary) const
01736 {
01737   if (isChromaHorCTBBoundary)
01738   {
01739     return abs(piSrc[-iOffset * 2] - 2 * piSrc[-iOffset * 2] + piSrc[-iOffset]);
01740   }
01741   else
01742   {
01743     return abs(piSrc[-iOffset * 3] - 2 * piSrc[-iOffset * 2] + piSrc[-iOffset]);
01744   }
01745 }
01746 
01747 inline int LoopFilter::xCalcDQ( Pel* piSrc, const int iOffset ) const
01748 {
01749   return abs( piSrc[0] - 2 * piSrc[iOffset] + piSrc[iOffset * 2] );
01750 }
01751 
01752 inline unsigned LoopFilter::BsSet(unsigned val, const ComponentID compIdx) const { return (val << (compIdx << 1)); }
01753 inline unsigned LoopFilter::BsGet(unsigned val, const ComponentID compIdx) const { return ((val >> (compIdx << 1)) & 3); }
01754
